package com.wipro.hibernate;import java.math.BigDecimal;public class Employee{private int employeeId;private String name,designation;private BigDecimal salary;public Employee(){}public int getEmployeeId(){return employeeId;}public void setEmployeeId(int v){employeeId=v;}public String getName(){return name;}public void setName(String v){name=v;}public String getDesignation(){return designation;}public void setDesignation(String v){designation=v;}public BigDecimal getSalary(){return salary;}public void setSalary(BigDecimal v){salary=v;}}